screenPanels.initJs:
function(container, apiUrl, tables) {
  const clientTable = tables[0];
  const contactTable = tables[1];
  const policyTable = tables[2];

  let selectedClientId = null;
  let allClients = clientTable.records || [];
  let allContacts = contactTable.records || [];
  let allPolicies = policyTable.records || [];

  // ========== 1. クライアント一覧の再描画 ==========
  function renderClientList(clients) {
    const tbody = container.querySelector("#client-tbody");
    if (!clients || clients.length === 0) {
      tbody.innerHTML = '<tr><td style="padding: 8px; color: var(--text-muted); text-align: center;">クライアントがありません</td></tr>';
      return;
    }
    tbody.innerHTML = clients.map(c => `
      <tr 
        data-id="${c.id}" 
        class="client-row" 
        style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;"
      >
        <td style="padding: 8px; color: var(--text); font-size: 12px;">
          <div style="font-weight: 500;">${c.クライアント名 || c.name || 'N/A'}</div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${c.業種 || ''}</div>
        </td>
      </tr>
    `).join("");

    // クライアント行クリックで選択
    container.querySelectorAll(".client-row").forEach(row => {
      row.addEventListener("click", () => {
        container.querySelectorAll(".client-row").forEach(r => r.style.background = "");
        row.style.background = "rgba(212, 175, 55, 0.1)";
        selectedClientId = row.dataset.id;
        renderTimeline();
        renderPolicy();
      });
    });
  }

  // ========== 2. 対応履歴タイムラインの再描画 ==========
  function renderTimeline() {
    const timelineContainer = container.querySelector("#timeline-container");
    const clientNameEl = container.querySelector("#selected-client-name");

    if (!selectedClientId) {
      timelineContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 20px;">クライアントを選択してください</div>';
      clientNameEl.textContent = "クライアントを選択してください";
      return;
    }

    const client = allClients.find(c => c.id === selectedClientId);
    if (client) {
      clientNameEl.textContent = client.クライアント名 || client.name || 'N/A';
    }

    const contacts = allContacts.filter(c => c.クライアントID === selectedClientId || c.clientId === selectedClientId);

    if (!contacts || contacts.length === 0) {
      timelineContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 20px;">対応履歴がありません</div>';
      return;
    }

    // 時系列ソート（新しい順）
    contacts.sort((a, b) => new Date(b.対応日時 || b.contactDate) - new Date(a.対応日時 || a.contactDate));

    timelineContainer.innerHTML = contacts.map((contact, idx) => {
      const dt = new Date(contact.対応日時 || contact.contactDate);
      const dateStr = dt.toLocaleString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      const typeColor = {
        '電話': '#ff6b6b',
        '訪問': '#ffa500',
        'メール': '#4ecdc4',
        '商談': '#d4af37',
        '提案': '#95e1d3'
      }[contact.対応種別 || contact.contactType] || '#9fb0d1';

      return `
        <div style="display: flex; gap: 10px; position: relative;">
          <div style="display: flex; flex-direction: column; align-items: center; gap: 4px;">
            <div style="width: 24px; height: 24px; border-radius: 50%; background: ${typeColor}; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 10px; font-weight: 600;">
              ${(contact.対応種別 || contact.contactType || '').charAt(0)}
            </div>
            ${idx < contacts.length - 1 ? `<div style="width: 2px; height: 20px; background: rgba(255,255,255,0.1);"></div>` : ''}
          </div>
          <div style="flex: 1; padding-bottom: 8px;">
            <div style="font-size: 11px; font-weight: 600; color: var(--text);">
              ${contact.対応種別 || contact.contactType || 'N/A'}
            </div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">
              ${dateStr} | ${contact.ユーザーID || contact.userId || '未設定'}
            </div>
            <div style="font-size: 11px; color: var(--text); margin-top: 4px; line-height: 1.4; padding: 6px; background: rgba(0,0,0,0.15); border-radius: 3px; border-left: 2px solid ${typeColor};">
              ${(contact.対応内容 || contact.content || '').substring(0, 100)}${(contact.対応内容 || contact.content || '').length > 100 ? '...' : ''}
            </div>
            <div style="font-size: 10px; color: #d4af37; margin-top: 3px;">
              結果: ${contact.対応結果 || contact.result || 'N/A'}
            </div>
            <div style="display: flex; gap: 6px; margin-top: 4px;">
              <button 
                class="edit-contact-btn" 
                data-id="${contact.id}" 
                style="padding: 3px 8px; font-size: 10px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); border-radius: 3px; cursor: pointer;"
              >編集</button>
              <button 
                class="delete-contact-btn" 
                data-id="${contact.id}" 
                style="padding: 3px 8px; font-size: 10px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: #ff6b6b; border-radius: 3px; cursor: pointer;"
              >削除</button>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }

  // ========== 3. 対応方針の表示 ==========
  function renderPolicy() {
    const policyPanel = container.querySelector("#policy-panel");

    if (!selectedClientId) {
      policyPanel.innerHTML = '方針が設定されていません';
      return;
    }

    const policies = allPolicies.filter(p => p.クライアントID === selectedClientId || p.clientId === selectedClientId);

    if (!policies || policies.length === 0) {
      policyPanel.innerHTML = '<div style="color: var(--text-muted);">方針が設定されていません</div>';
      return;
    }

    const policy = policies[0]; // 最初の有効な方針を表示
    const priorityLabel = { 1: '高', 2: '中', 3: '低' }[policy.優先度 || policy.priority] || 'N/A';

    policyPanel.innerHTML = `
      <div style="margin-bottom: 6px;">
        <div style="font-weight: 600; color: var(--text); font-size: 11px;">${policy.方針名 || policy.policyName || 'N/A'}</div>
        <div style="font-size: 10px; color: #d4af37; margin-top: 2px;">優先度: ${priorityLabel}</div>
      </div>
      <div style="font-size: 10px; color: var(--text); line-height: 1.4; padding: 6px; background: rgba(0,0,0,0.15); border-radius: 3px;">
        ${(policy.方針内容 || policy.policyContent || '').substring(0, 150)}${(policy.方針内容 || policy.policyContent || '').length > 150 ? '...' : ''}
      </div>
      <div style="font-size: 9px; color: var(--text-muted); margin-top: 4px;">
        対応頻度: ${policy.対応頻度 || policy.frequency || 'N/A'}
      </div>
    `;
  }

  // ========== 4. 初期データ読み込み ==========
  window.aivicApi.list(0).then(rows => {
    allClients = rows || [];
    renderClientList(allClients);
  }).catch(() => renderClientList(allClients));

  window.aivicApi.list(1).then(rows => {
    allContacts = rows || [];
  }).catch(() => {});

  window.aivicApi.list(2).then(rows => {
    allPolicies = rows || [];
  }).catch(() => {});

  // ========== 5. クライアント検索 ==========
  container.querySelector("#btn-search-client").addEventListener("click", () => {
    const keyword = container.querySelector("#client-search-input").value.toLowerCase();
    const filtered = allClients.filter(c => 
      (c.クライアント名 || c.name || '').toLowerCase().includes(keyword) ||
      (c.業種 || '').toLowerCase().includes(keyword)
    );
    renderClientList(filtered);
  });

  // ========== 6. 対応記録の保存 ==========
  container.querySelector("#btn-save-contact").addEventListener("click", async () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }

    const datetime = container.querySelector("#contact-datetime").value;
    const userId = container.querySelector("#contact-user").value;
    const contactType = container.querySelector("#contact-type").value;
    const result = container.querySelector("#contact-result").value;
    const content = container.querySelector("#contact-content").value;

    if (!datetime || !userId || !contactType || !result || !content) {
      alert("すべての項目を入力してください");
      return;
    }

    const newContact = {
      クライアントID: selectedClientId,
      ユーザーID: userId,
      対応種別: contactType,
      対応日時: datetime,
      対応内容: content,
      対応結果: result,
      ステータス: "完了"
    };

    const saved = await window.aivicApi.save(1, newContact);
    if (saved) {
      container.querySelector("#contact-datetime").value = "";
      container.querySelector("#contact-user").value = "";
      container.querySelector("#contact-type").value = "";
      container.querySelector("#contact-result").value = "";
      container.querySelector("#contact-content").value = "";

      window.aivicApi.list(1).then(rows => {
        allContacts = rows || [];
        renderTimeline();
      });
    }
  });

  // ========== 7. 対応履歴の削除 ==========
  container.addEventListener("click", async e => {
    const deleteBtn = e.target.closest(".delete-contact-btn");
    if (deleteBtn) {
      if (!confirm("この対応履歴を削除しますか？")) return;
      const contactId = deleteBtn.dataset.id;
      await window.aivicApi.delete(1, contactId);
      window.aivicApi.list(1).then(rows => {
        allContacts = rows || [];
        renderTimeline();
      });
    }

    const editBtn = e.target.closest(".edit-contact-btn");
    if (editBtn) {
      const contactId = editBtn.dataset.id;
      const contact = allContacts.find(c => c.id === contactId);
      if (contact) {
        container.querySelector("#contact-datetime").value = contact.対応日時 || contact.contactDate || "";
        container.querySelector("#contact-user").value = contact.ユーザーID || contact.userId || "";
        container.querySelector("#contact-type").value = contact.対応種別 || contact.contactType || "";
        container.querySelector("#contact-result").value = contact.対応結果 || contact.result || "";
        container.querySelector("#contact-content").value = contact.対応内容 || contact.content || "";
        container.querySelector("#contact-content").focus();
      }
    }
  });
}

function(container, apiUrl, tables) {
  const clientSelect = container.querySelector("#client-select");
  const projectSelect = container.querySelector("#project-select");
  const contactDatetime = container.querySelector("#contact-datetime");
  const contactMethod = container.querySelector("#contact-method");
  const contactContent = container.querySelector("#contact-content");
  const policySelect = container.querySelector("#policy-select");
  const nextContactDate = container.querySelector("#next-contact-date");
  const attachmentFile = container.querySelector("#attachment-file");
  const assignedUserDiv = container.querySelector("#assigned-user");
  const historyPreview = container.querySelector("#history-preview");
  const btnSave = container.querySelector("#btn-save");
  const btnCancel = container.querySelector("#btn-cancel");

  // テーブルインデックス（対応履歴テーブル）
  const contactHistoryTableIndex = 0;

  // 初期データから対応履歴を描画
  function renderHistoryPreview(rows) {
    historyPreview.innerHTML = (rows || []).slice(0, 5).map(row => `
      <div style="padding: 10px; background: var(--bg-card); border-radius: 4px; border-left: 3px solid var(--primary); font-size: 12px;">
        <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
          <span style="font-weight: 600; color: var(--text);">${row.対応種別 || '対応'}</span>
          <span style="color: var(--text-muted); font-size: 11px;">${row.対応日時 ? new Date(row.対応日時).toLocaleDateString('ja-JP') : '-'}</span>
        </div>
        <div style="color: var(--text-muted); margin-bottom: 4px; line-height: 1.4;">${(row.対応内容 || '').substring(0, 60)}${(row.対応内容 || '').length > 60 ? '...' : ''}</div>
        <div style="font-size: 11px; color: var(--text-muted);">
          ${row.成果 ? `<span style="display: inline-block; background: rgba(255,165,0,0.15); color: #ffa500; padding: 2px 6px; border-radius: 3px; margin-right: 4px;">${row.成果}</span>` : ''}
        </div>
      </div>
    `).join("");
  }

  // 初期データを即座に描画
  if (tables && tables[contactHistoryTableIndex] && tables[contactHistoryTableIndex].records) {
    renderHistoryPreview(tables[contactHistoryTableIndex].records);
  }

  // 担当者を現在のユーザーに設定（ダミー）
  assignedUserDiv.textContent = "営業太郎（営業部）";

  // 登録ボタンのイベントリスナー
  btnSave.addEventListener("click", async () => {
    const clientId = clientSelect.value;
    const projectId = projectSelect.value;
    const datetime = contactDatetime.value;
    const method = contactMethod.value;
    const content = contactContent.value;
    const policy = policySelect.value;
    const nextDate = nextContactDate.value;

    if (!clientId || !datetime || !method || !content) {
      alert("クライアント、対応日時、対応方法、対応内容は必須です");
      return;
    }

    const newRecord = {
      クライアントID: clientId,
      案件ID: projectId || null,
      ユーザーID: "current-user-id",
      対応種別: method,
      対応日時: datetime,
      対応内容: content,
      次回対応予定日: nextDate || null,
      ステータス: "完了",
      成果: policy,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(contactHistoryTableIndex, newRecord);
    if (saved) {
      alert("対応履歴を登録しました");
      // フォームをリセット
      clientSelect.value = "";
      projectSelect.value = "";
      contactDatetime.value = "";
      contactMethod.value = "";
      contactContent.value = "";
      policySelect.value = "";
      nextContactDate.value = "";
      attachmentFile.value = "";

      // 履歴を再読み込み
      const updated = await window.aivicApi.list(contactHistoryTableIndex);
      if (updated) renderHistoryPreview(updated);
    }
  });

  // キャンセルボタンのイベントリスナー
  btnCancel.addEventListener("click", () => {
    if (confirm("入力内容を破棄してもよろしいですか？")) {
      clientSelect.value = "";
      projectSelect.value = "";
      contactDatetime.value = "";
      contactMethod.value = "";
      contactContent.value = "";
      policySelect.value = "";
      nextContactDate.value = "";
      attachmentFile.value = "";
    }
  });

  // クライアント選択時に対応方針を更新（ダミー）
  clientSelect.addEventListener("change", () => {
    if (clientSelect.value) {
      policySelect.value = "follow-up";
    }
  });

  // 最新データを定期的に取得して履歴を更新
  setInterval(async () => {
    const latest = await window.aivicApi.list(contactHistoryTableIndex);
    if (latest) renderHistoryPreview(latest);
  }, 30000);
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 対応方針テーブルは tables[0] と仮定
  const tableIndex = 0;

  // 1. 初期データ描画（関連案件）
  function renderRelatedProjects(projects) {
    const tbody = container.querySelector("#related-projects-tbody");
    if (!projects || projects.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 1rem; text-align: center; color: var(--text-muted);">関連案件はありません</td></tr>';
      return;
    }
    tbody.innerHTML = projects.map(p => `
      <tr>
        <td style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.05); color: var(--text);">${p.projectName || ''}</td>
        <td style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.05); color: var(--text);">${p.status || ''}</td>
        <td style="padding: 0.5rem; border-bottom: 1px solid rgba(255,255,255,0.05); color: var(--text); text-align: right;">¥${(p.estimatedAmount || 0).toLocaleString()}</td>
      </tr>
    `).join('');
  }

  // 2. 過去対応履歴を描画
  function renderHistoryTimeline(histories) {
    const timeline = container.querySelector("#history-timeline");
    if (!histories || histories.length === 0) {
      timeline.innerHTML = '<div style="padding: 1rem; text-align: center; color: var(--text-muted);">対応履歴がありません</div>';
      return;
    }
    timeline.innerHTML = histories.slice(0, 5).map(h => `
      <div style="display: flex; gap: 1rem; padding: 0.75rem; background: rgba(0,0,0,0.15); border-radius: 0.375rem; border-left: 3px solid #ff6a00;">
        <div style="font-size: 0.75rem; color: var(--text-muted); min-width: 5rem;">${new Date(h.contactDate).toLocaleDateString('ja-JP')}</div>
        <div style="flex: 1;">
          <div style="font-size: 0.875rem; color: var(--text); font-weight: 600;">${h.contactType || ''}</div>
          <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.25rem;">営業担当: ${h.userName || ''} | 成果: ${h.result || ''}</div>
        </div>
      </div>
    `).join('');
  }

  // 3. タブ切り替え処理
  const tabButtons = container.querySelectorAll(".tab-btn");
  tabButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      const tabName = btn.dataset.tab;
      // 全タブを非表示
      container.querySelectorAll(".tab-content").forEach(tab => tab.style.display = "none");
      // 選択タブを表示
      container.querySelector(`#tab-${tabName}`).style.display = "block";
      // ボタンのスタイル更新
      tabButtons.forEach(b => {
        b.style.color = "var(--text-muted)";
        b.style.borderBottomColor = "transparent";
      });
      btn.style.color = "var(--text)";
      btn.style.borderBottomColor = "var(--primary)";
    });
  });

  // 4. 保存ボタン処理
  container.querySelector("[data-testid='save-button']").addEventListener("click", async () => {
    const clientId = container.querySelector("[data-testid='client-select']").value;
    const policyName = container.querySelector("[data-testid='policy-name-input']").value;
    const policyDescription = container.querySelector("[data-testid='policy-description-textarea']").value;
    const priority = container.querySelector("input[name='priority']:checked")?.value || "2";
    const contactFrequency = container.querySelector("[data-testid='contact-frequency-select']").value;
    const assignedUserId = container.querySelector("[data-testid='assigned-user-select']").value;
    const startDate = container.querySelector("[data-testid='start-date-input']").value;
    const endDate = container.querySelector("[data-testid='end-date-input']").value;
    const channels = Array.from(container.querySelectorAll("input[name='channels']:checked")).map(c => c.value).join(",");

    if (!clientId || !policyName || !policyDescription || !assignedUserId || !startDate) {
      alert("必須項目を入力してください");
      return;
    }

    const payload = {
      clientId,
      policyName,
      policyDescription,
      priority: parseInt(priority),
      contactFrequency,
      assignedUserId,
      startDate,
      endDate: endDate || null,
      channels,
      status: container.querySelector("[data-testid='policy-status-select']").value || "有効"
    };

    const saved = await window.aivicApi.save(tableIndex, payload);
    if (saved) {
      alert("対応方針を保存しました");
      // フォームをリセット
      container.querySelector("[data-testid='policy-name-input']").value = "";
      container.querySelector("[data-testid='policy-description-textarea']").value = "";
      container.querySelector("[data-testid='contact-frequency-select']").value = "";
      container.querySelector("[data-testid='assigned-user-select']").value = "";
      container.querySelector("[data-testid='start-date-input']").value = "";
      container.querySelector("[data-testid='end-date-input']").value = "";
    }
  });

  // 5. キャンセルボタン処理
  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    window.showScreen("scr-1781408840123");
  });

  // 6. ダッシュボードボタン処理
  container.querySelector("[data-testid='back-to-dashboard']").addEventListener("click", () => {
    window.showScreen("scr-1781408945964");
  });

  // 7. 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    if (rows && rows.length > 0) {
      // 最初のレコードを表示（実装では選択されたクライアントに基づいてフィルタリング）
      const firstRecord = rows[0];
      container.querySelector("[data-testid='policy-name-input']").value = firstRecord.policyName || "";
      container.querySelector("[data-testid='policy-description-textarea']").value = firstRecord.policyDescription || "";
      container.querySelector("[data-testid='contact-frequency-select']").value = firstRecord.contactFrequency || "";
      container.querySelector("[data-testid='assigned-user-select']").value = firstRecord.assignedUserId || "";
      container.querySelector("[data-testid='start-date-input']").value = firstRecord.startDate ? firstRecord.startDate.split('T')[0] : "";
      container.querySelector("[data-testid='end-date-input']").value = firstRecord.endDate ? firstRecord.endDate.split('T')[0] : "";

      // 関連案件とタイムラインのダミーデータ
      renderRelatedProjects([
        { projectName: "システム導入案件", status: "進行中", estimatedAmount: 2500000 },
        { projectName: "保守契約更新", status: "提案済み", estimatedAmount: 500000 }
      ]);
      renderHistoryTimeline([
        { contactDate: "2024-12-15", contactType: "電話対応", userName: "田中太郎", result: "見積提出" },
        { contactDate: "2024-12-08", contactType: "訪問", userName: "田中太郎", result: "資料送付" }
      ]);
    }
  });
}

function(container, apiUrl, tables) {
  let currentStep = 1;
  const totalSteps = 3;
  const formData = {};

  // ステップ表示の更新
  function updateStepDisplay() {
    container.querySelectorAll(".step-indicator").forEach(el => {
      const step = parseInt(el.dataset.step);
      const isActive = step === currentStep;
      el.style.opacity = isActive ? "1" : "0.5";
      el.querySelector("div").style.background = isActive ? "var(--primary)" : "rgba(255,255,255,0.1)";
      el.querySelector("div").style.color = isActive ? "#fff" : "var(--text-muted)";
      el.querySelector("span").style.color = isActive ? "var(--text)" : "var(--text-muted)";
    });

    container.querySelectorAll(".step-form").forEach(el => {
      el.style.display = "none";
    });
    container.querySelector(`#step-${currentStep}-form`).style.display = "block";

    // ボタン表示の切り替え
    const btnBack = container.querySelector("#btn-back");
    const btnNext = container.querySelector("#btn-next");
    const btnSave = container.querySelector("#btn-save");

    btnBack.style.display = currentStep > 1 ? "block" : "none";
    btnNext.style.display = currentStep < totalSteps ? "block" : "none";
    btnSave.style.display = currentStep === totalSteps ? "block" : "none";
  }

  // フォームデータの収集
  function collectFormData() {
    formData.projectName = container.querySelector("#project-name").value;
    formData.clientId = container.querySelector("#client-select").value;
    formData.status = container.querySelector("#project-status").value;
    formData.type = container.querySelector("#project-type").value;
    formData.assignedUserId = container.querySelector("#assigned-user").value;
    formData.expectedAmount = parseInt(container.querySelector("#expected-amount").value) || 0;
    formData.startDate = container.querySelector("#start-date").value;
    formData.endDate = container.querySelector("#end-date").value;
    formData.description = container.querySelector("#project-description").value;

    const policies = [];
    if (container.querySelector("#policy-aggressive").checked) policies.push("積極営業");
    if (container.querySelector("#policy-regular").checked) policies.push("定期フォローアップ");
    if (container.querySelector("#policy-conservative").checked) policies.push("保守的対応");
    if (container.querySelector("#policy-custom").checked) policies.push("カスタム対応");
    formData.policies = policies;
  }

  // サマリー表示の更新
  function updateSummary() {
    collectFormData();
    container.querySelector("#summary-name").textContent = formData.projectName || "-";
    container.querySelector("#summary-client").textContent = container.querySelector("#client-select").options[container.querySelector("#client-select").selectedIndex]?.text || "-";
    container.querySelector("#summary-status").textContent = formData.status || "-";
    container.querySelector("#summary-user").textContent = container.querySelector("#assigned-user").options[container.querySelector("#assigned-user").selectedIndex]?.text || "-";
    container.querySelector("#summary-amount").textContent = formData.expectedAmount ? `¥${formData.expectedAmount.toLocaleString()}` : "-";
    container.querySelector("#summary-start").textContent = formData.startDate || "-";
  }

  // バリデーション
  function validateStep(step) {
    if (step === 1) {
      const name = container.querySelector("#project-name").value.trim();
      const client = container.querySelector("#client-select").value;
      const status = container.querySelector("#project-status").value;
      const type = container.querySelector("#project-type").value;
      const user = container.querySelector("#assigned-user").value;
      if (!name || !client || !status || !type || !user) {
        showError("必須項目を入力してください");
        return false;
      }
    }
    return true;
  }

  // エラー表示
  function showError(msg) {
    const errorEl = container.querySelector("#error-message");
    errorEl.textContent = msg;
    errorEl.style.display = "block";
    setTimeout(() => { errorEl.style.display = "none"; }, 3000);
  }

  // 成功表示
  function showSuccess() {
    const successEl = container.querySelector("#success-message");
    successEl.style.display = "block";
    setTimeout(() => { successEl.style.display = "none"; }, 3000);
  }

  // ファイルドロップゾーン
  const dropZone = container.querySelector("#file-drop-zone");
  const fileInput = container.querySelector("#file-input");
  const fileList = container.querySelector("#file-list");

  dropZone.addEventListener("click", () => fileInput.click());
  dropZone.addEventListener("dragover", e => {
    e.preventDefault();
    dropZone.style.background = "rgba(255,165,0,0.1)";
  });
  dropZone.addEventListener("dragleave", () => {
    dropZone.style.background = "rgba(0,0,0,0.15)";
  });
  dropZone.addEventListener("drop", e => {
    e.preventDefault();
    dropZone.style.background = "rgba(0,0,0,0.15)";
    fileInput.files = e.dataTransfer.files;
    updateFileList();
  });
  fileInput.addEventListener("change", updateFileList);

  function updateFileList() {
    fileList.innerHTML = Array.from(fileInput.files).map(f => `<div>📎 ${f.name}</div>`).join("");
  }

  // ボタンイベント
  container.querySelector("#btn-next").addEventListener("click", () => {
    if (!validateStep(currentStep)) return;
    if (currentStep === 2) updateSummary();
    currentStep++;
    updateStepDisplay();
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    currentStep--;
    updateStepDisplay();
  });

  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力を中止しますか？")) {
      window.showScreen("scr-1781408811435"); // クライアント統合ダッシュボード
    }
  });

  container.querySelector("#btn-save").addEventListener("click", async () => {
    collectFormData();
    if (!formData.projectName || !formData.clientId || !formData.status || !formData.type || !formData.assignedUserId) {
      showError("必須項目を入力してください");
      return;
    }

    const payload = {
      案件名: formData.projectName,
      クライアントID: formData.clientId,
      ステータス: formData.status,
      案件種別: formData.type,
      担当ユーザーID: formData.assignedUserId,
      予想金額: formData.expectedAmount,
      案件説明: formData.description,
      開始日: formData.startDate,
      終了日: formData.endDate,
      対応方針: formData.policies.join(", ")
    };

    const saved = await window.aivicApi.save(6, payload); // tableIndex 6 = 案件テーブル
    if (saved) {
      showSuccess();
      setTimeout(() => {
        window.showScreen("scr-1781408811435"); // クライアント統合ダッシュボード
      }, 1500);
    }
  });

  container.querySelector("#btn-view-history").addEventListener("click", () => {
    window.showScreen("scr-1781408840123"); // 対応履歴・対応方針管理画面
  });

  // 初期表示
  updateStepDisplay();
}

