          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">メール</div>
            <div style="color: var(--text); word-break: break-all;">${client.メールアドレス || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">電話</div>
            <div style="color: var(--text);">${client.電話番号 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">住所</div>
            <div style="color: var(--text); font-size: 0.75rem;">${client.住所 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">ステータス</div>
            <div style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; font-size: 0.75rem; font-weight: 600; background: ${getStatusColor(client.ステータス)}; color: #fff;">
              ${client.ステータス || '—'}
            </div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">契約状況</div>
            <div style="color: var(--text);">${client.契約状況 || '—'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 0.125rem;">推定売上額</div>
            <div style="color: var(--text); font-weight: 600;">${client.推定売上額 ? '¥' + client.推定売上額.toLocaleString() : '—'}</div>
          </div>
