      <div style="border-top: 1px solid rgba(255,255,255,0.1); padding-top: 1rem; margin-bottom: 1rem;">
        <h4 style="font-size: 0.8125rem; font-weight: 700; color: var(--text); margin-bottom: 0.5rem; text-transform: uppercase; letter-spacing: 0.5px;">対応履歴</h4>
        <div id="detail-history" style="font-size: 0.75rem; max-height: 150px; overflow-y: auto;">
          <div style="color: var(--text-muted);">読込中...</div>
