  btnSearch.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(clientTableIndex);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const nameMatch = !filterClientName.value || (r.クライアント名 || '').includes(filterClientName.value);
      const idMatch = !filterClientId.value || (r.クライアントID || r.id || '').includes(filterClientId.value);
