      const regionMatch = !filterRegion.value || (r.住所 || '').includes(filterRegion.value);
      const projectStatusMatch = !filterProjectStatus.value || r.ステータス === filterProjectStatus.value;
      const approachMatch = !filterApproach.value || r.対応方針 === filterApproach.value;
      const contractMatch = !filterContractStatus.value || r.契約状況 === filterContractStatus.value;

      let dateMatch = true;
      if (filterDateFrom.value || filterDateTo.value) {
        const lastContact = r.最終接触日 ? new Date(r.最終接触日) : null;
        if (filterDateFrom.value && lastContact) {
          dateMatch = dateMatch && lastContact >= new Date(filterDateFrom.value);
        }
        if (filterDateTo.value && lastContact) {
          dateMatch = dateMatch && lastContact <= new Date(filterDateTo.value);
        }
      }

      return nameMatch && idMatch && industryMatch && regionMatch && projectStatusMatch && approachMatch && contractMatch && dateMatch;
    });

    renderClientRows(filtered);
  });

