      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.クライアントID || r.id || "",
        `"${(r.クライアント名 || "").replace(/"/g, '""')}"`,
        r.業種 || "",
        r.代表者名 || "",
        r.メールアドレス || "",
        r.電話番号 || "",
        `"${(r.住所 || "").replace(/"/g, '""')}"`,
        r.ステータス || "",
        r.契約状況 || "",
        r.推定売上額 || "",
        r.最終接触日 ? new Date(r.最終接触日).toLocaleDateString('ja-JP') : ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `clients_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 初期データ表示
  window.aivicApi.list(clientTableIndex).then(rows => {
    if (rows && rows.length > 0) {
      renderClientRows(rows);
    }
  });
}

