    const todayActions = (allHistories || []).filter(h => {
      const hDate = h.対応日時 ? new Date(h.対応日時).toDateString() : '';
      return hDate === new Date().toDateString();
    }).length;

    container.querySelector("#kpi-order-count").textContent = orderCount;
    container.querySelector("#kpi-revenue-forecast").textContent = '¥' + revenueForecast.toLocaleString();
