    renderHistoryTimeline(clientHistories);

    const clientProjects = (allProjects || []).filter(p => p.クライアントID === clientId);
    renderProjectsBoard(clientProjects);

    const clientPolicies = (allPolicies || []).filter(p => p.クライアントID === clientId);
    renderPolicyInfo(clientPolicies);

    renderClientList(allClients);
  }

  // ===== 2. 初期データ読み込み =====

  async function loadAllData() {
    try {
      allClients = await window.aivicApi.list(clientTableIdx) || tables[clientTableIdx]?.records || [];
      allHistories = await window.aivicApi.list(historyTableIdx) || tables[historyTableIdx]?.records || [];
      allPolicies = await window.aivicApi.list(policyTableIdx) || tables[policyTableIdx]?.records || [];
      allOrders = await window.aivicApi.list(orderTableIdx) || tables[orderTableIdx]?.records || [];
      allProjects = await window.aivicApi.list(projectTableIdx) || tables[projectTableIdx]?.records || [];

      renderClientList(allClients);
      updateKPIs();
    } catch (e) {
      console.error("Data load error:", e);
      allClients = tables[clientTableIdx]?.records || [];
      allHistories = tables[historyTableIdx]?.records || [];
      allPolicies = tables[policyTableIdx]?.records || [];
      allOrders = tables[orderTableIdx]?.records || [];
      allProjects = tables[projectTableIdx]?.records || [];
      renderClientList(allClients);
      updateKPIs();
    }
  }

  loadAllData();

  // ===== 3. イベントリスナー =====

  // クライアント検索
  container.querySelector("#btn-search-client").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-client-name").value.toLowerCase();
    const status = container.querySelector("#filter-status").value;
    const filtered = allClients.filter(c => {
      const matchName = !keyword || (c.クライアント名 || '').toLowerCase().includes(keyword);
