      btn.classList.add("active");
      btn.style.color = "var(--text)";
      btn.style.borderBottomColor = "var(--primary)";

      container.querySelectorAll(".tab-content").forEach(c => c.style.display = "none");
      const tabId = btn.dataset.tab;
      const tabEl = container.querySelector(`#tab-${tabId}`);
      if (tabEl) tabEl.style.display = "block";
    });
  });

  // ボタンイベント
  container.querySelector("#btn-add-client").addEventListener("click", () => {
    window.showScreen("scr-1781408824557");
  });

  container.querySelector("#btn-edit-client").addEventListener("click", () => {
    if (selectedClientId) {
      window.showScreen("scr-1781408824557");
    }
  });

  container.querySelector("#btn-add-history").addEventListener("click", () => {
    window.showScreen("scr-1781408865891");
  });

  container.querySelector("#btn-add-project").addEventListener("click", () => {
    window.showScreen("scr-1781408904580");
  });

  container.querySelector("#btn-set-policy").addEventListener("click", () => {
    window.showScreen("scr-1781408878914");
