}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const clientTableIdx = 0;
  const historyTableIdx = 1;
  const policyTableIdx = 2;
  const projectTableIdx = 3;
  const orderTableIdx = 4;

  let selectedClientId = null;
  let allClients = [];
  let allHistories = [];
  let allPolicies = [];
  let allProjects = [];
  let allOrders = [];

  // ===== 1. 再描画関数 =====
  function renderClients(rows) {
    const tbody = container.querySelector("#client-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
        <td style="padding: 8px; color: var(--text);">${r.クライアント名 || r.name || ""}</td>
        <td style="padding: 8px;">
          <span style="display: inline-block; padding: 2px 6px; background: ${getStatusColor(r.ステータス || r.status)}; color: #fff; border-radius: 3px; font-size: 11px;">
            ${r.ステータス || r.status || ""}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    const colors = {
      "見込み客": "rgba(100,200,255,0.3)",
      "既存顧客": "rgba(74,222,128,0.3)",
      "休止中": "rgba(255,106,0,0.3)"
    };
    return colors[status] || "rgba(100,100,100,0.3)";
  }

  function renderTimeline(histories) {
    const container = document.querySelector("#timeline-container");
    if (!histories || histories.length === 0) {
      container.innerHTML = '<div style="font-size: 11px; color: var(--text-muted); text-align: center; padding: 16px;">対応履歴がありません</div>';
      return;
    }
    container.innerHTML = histories.slice(0, 5).map(h => `
      <div style="display: flex; gap: 8px;">
        <div style="width: 3px; background: ${getHistoryColor(h.対応種別 || h.type)}; border-radius: 2px; flex-shrink: 0;"></div>
        <div style="flex: 1; min-width: 0;">
          <div style="font-size: 12px; color: var(--text); font-weight: 500;">${h.対応種別 || h.type || ""}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${formatDate(h.対応日時 || h.date)}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px; line-height: 1.4;">${(h.対応内容 || h.content || "").substring(0, 60)}</div>
        </div>
      </div>
    `).join("");
  }

  function getHistoryColor(type) {
    const colors = {
      "電話": "#64c8ff",
      "メール": "#ffa500",
      "訪問": "#4ade80",
      "商談": "#ff6a00",
      "提案": "#a78bfa"
    };
    return colors[type] || "var(--primary)";
  }

  function formatDate(dateStr) {
    if (!dateStr) return "";
    const d = new Date(dateStr);
    return d.toLocaleDateString("ja-JP", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });
  }

  function renderProjects(rows) {
    const tbody = container.querySelector("#project-tbody");
    tbody.innerHTML = rows.slice(0, 6).map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px; color: var(--text);">${r.案件名 || r.name || ""}</td>
        <td style="padding: 6px; text-align: center; color: #64c8ff; font-weight: 600;">${r.成約確度 || r.probability || 0}%</td>
      </tr>
    `).join("");
  }

  // ===== 2. 初期データ読み込み =====
  async function loadInitialData() {
    try {
      allClients = (await window.aivicApi.list(clientTableIdx)) || tables[clientTableIdx]?.records || [];
      allHistories = (await window.aivicApi.list(historyTableIdx)) || tables[historyTableIdx]?.records || [];
      allPolicies = (await window.aivicApi.list(policyTableIdx)) || tables[policyTableIdx]?.records || [];
      allProjects = (await window.aivicApi.list(projectTableIdx)) || tables[projectTableIdx]?.records || [];
      allOrders = (await window.aivicApi.list(orderTableIdx)) || tables[orderTableIdx]?.records || [];

      renderClients(allClients);
      drawRevenueChart();
    } catch (e) {
      console.error("Data load error:", e);
      renderClients(tables[clientTableIdx]?.records || []);
    }
  }

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search-client").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search-client").value.toLowerCase();
    const status = container.querySelector("#filter-status").value;

    let filtered = allClients;
    if (keyword) {
      filtered = filtered.filter(c => 
        (c.クライアント名 || c.name || "").toLowerCase().includes(keyword) ||
        (c.業種 || c.industry || "").toLowerCase().includes(keyword)
      );
    }
    if (status) {
      filtered = filtered.filter(c => (c.ステータス || c.status) === status);
    }
    renderClients(filtered);
  });

  // ===== 4. クライアント行クリック =====
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tr[data-id]");
    if (row && container.querySelector("#client-tbody").contains(row)) {
      selectedClientId = row.dataset.id;

      // 対応履歴フィルタリング
      const clientHistories = allHistories.filter(h => h.クライアントID === selectedClientId || h.clientId === selectedClientId);
      renderTimeline(clientHistories);

      // 対応方針表示
      const policy = allPolicies.find(p => p.クライアントID === selectedClientId || p.clientId === selectedClientId);
      const policyBadge = container.querySelector("#policy-badge");
      if (policy) {
        policyBadge.style.display = "block";
        container.querySelector("#policy-name").textContent = policy.方針名 || policy.name || "";
        container.querySelector("#policy-desc").textContent = policy.方針内容 || policy.description || "";
      } else {
        policyBadge.style.display = "none";
      }

      // 案件フィルタリング
      const clientProjects = allProjects.filter(p => p.クライアントID === selectedClientId || p.clientId === selectedClientId);
      renderProjects(clientProjects);

      // 行をハイライト
      container.querySelectorAll("#client-tbody tr").forEach(tr => tr.style.background = "");
      row.style.background = "rgba(255,255,255,0.1)";
    }
  });

  // ===== 5. 対応履歴追加ボタン =====
  container.querySelector("#btn-add-history").addEventListener("click", () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }
    window.showScreen("scr-1781408865891");
  });

  // ===== 6. 案件作成ボタン =====
  container.querySelector("#btn-add-project").addEventListener("click", () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }
    window.showScreen("scr-1781408904580");
  });

  // ===== 7. 受注一覧ボタン =====
  container.querySelector("#btn-view-orders").addEventListener("click", () => {
    window.showScreen("scr-1781408853048");
  });

  // ===== 8. 売上予測チャート描画 =====
  function drawRevenueChart() {
    const canvas = container.querySelector("#revenue-chart");
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;

    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const padding = 30;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;

    // ダミーデータ: 3ヶ月の売上予測
    const data = [800, 1200, 1400];
    const labels = ["1月", "2月", "3月"];
    const maxVal = 1500;

    // 背景
    ctx.fillStyle = "rgba(0,0,0,0)";
    ctx.fillRect(0, 0, w, h);

    // グリッドライン
    ctx.strokeStyle = "rgba(255,255,255,0.1)";
    ctx.lineWidth = 1;
    for (let i = 0; i <= 3; i++) {
      const y = padding + (graphH / 3) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(w - padding, y);
      ctx.stroke();
    }

    // バー描画
    const barW = graphW / (data.length * 1.5);
    data.forEach((val, idx) => {
      const x = padding + (graphW / data.length) * idx + (graphW / data.length - barW) / 2;
      const barH = (val / maxVal) * graphH;
      const y = padding + graphH - barH;

      // グラデーション
      const grad = ctx.createLinearGradient(0, y, 0, padding + graphH);
      grad.addColorStop(0, "#ff6a00");
      grad.addColorStop(1, "#ffa500");
      ctx.fillStyle = grad;
      ctx.fillRect(x, y, barW, barH);

      // ラベル
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(labels[idx], x + barW / 2, padding + graphH + 15);
      ctx.fillText("¥" + (val / 100).toFixed(0) + "万", x + barW / 2, y - 5);
    });

    // 軸
    ctx.strokeStyle = "rgba(255,255,255,0.2)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + graphH);
    ctx.lineTo(w - padding, padding + graphH);
    ctx.stroke();
  }

  // ===== 初期化実行 =====
  loadInitialData();
}
